/**
 * Generate 4 authentic syllabus chapters for any subject
 */
export function generateDefaultChaptersForSubject(
  subjectId: string,
  subjectName: string,
  gradeId: number,
  boardId: string = 'cbse'
): Chapter[] {
  const isPrimary = gradeId <= 5;
  const isSenior = gradeId >= 9;
  const sLower = subjectName.toLowerCase();

  if (sLower.includes('hindi') || sLower.includes('हिंदी')) {
    return [
      { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: 'वर्णमाला, शब्द रचना एवं उच्चारण', description: 'स्वर, व्यंजन, मात्राएं एवं शुद्ध उच्चारण अभ्यास।', estMinutes: 25, learningObjectives: ['वर्णमाला की समझ', 'शुद्ध शब्द निर्माण'], status: 'published' },
      { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: 'रोचक बाल कहानियां एवं गद्य पाठ', description: 'प्रेरणादायक कहानियां, चरित्र चित्रण एवं सीख।', estMinutes: 30, learningObjectives: ['कहानी का सार समझना', 'नैतिक मूल्यों का विकास'], status: 'published' },
      { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: 'सुरीली कविताएं एवं पद्य भाव', description: 'लयबद्ध कविताएं, तुकबंदी एवं भावार्थ।', estMinutes: 25, learningObjectives: ['काव्य सौंदर्य की समझ', 'सस्वर पठन कौशल'], status: 'published' },
      { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: 'व्यावहारिक व्याकरण एवं रचनात्मक लेखन', description: 'संज्ञा, सर्वनाम, विलोम शब्द, वाक्य रचना एवं लघु निबंध।', estMinutes: 30, learningObjectives: ['व्याकरण के नियमों का प्रयोग', 'रचनात्मक अभिव्यक्ति'], status: 'published' },
    ];
  }

  if (sLower.includes('bengali') || sLower.includes('বাংলা')) {
    return [
      { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: 'বর্ণ পরিচয় ও শব্দ গঠন (Phonics & Words)', description: 'স্বরবর্ণ, ব্যঞ্জনবর্ণ, কার চিহ্ন ও যুক্তাক্ষর অনুশীলন।', estMinutes: 25, learningObjectives: ['বর্ণের সঠিক উচ্চারণ', 'যুক্তাক্ষর গঠন'], status: 'published' },
      { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: 'ছোটদের সেরা গল্প (Selected Stories)', description: 'আকর্ষণীয় রূপকথা ও নীতিশিক্ষার গল্প।', estMinutes: 30, learningObjectives: ['গল্পের মূল ভাব বোঝা', 'শব্দভাণ্ডার বৃদ্ধি'], status: 'published' },
      { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: 'ছড়া ও কবিতা পাঠ (Rhymes & Poetry)', description: 'রবীন্দ্রনাথ ও সুকুমার রায়ের বিখ্যাত শিশুতোষ কবিতা।', estMinutes: 25, learningObjectives: ['কবিতার ছন্দ উপভোগ', 'আবৃত্তি দক্ষতা'], status: 'published' },
      { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: 'ব্যবহারিক বাংলা ব্যাকরণ ও অনুচ্ছেদ রচনা', description: 'পদ পরিচয়, সমার্থক শব্দ, বিপরীত শব্দ ও ছোট রচনা।', estMinutes: 30, learningObjectives: ['শুদ্ধ বাক্য প্রয়োগ', 'লেখনী শক্তির বিকাশ'], status: 'published' },
    ];
  }

  if (sLower.includes('sanskrit') || sLower.includes('संस्कृत')) {
    return [
      { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: 'संस्कृत वर्णमाला एवं प्राथमिक परिचयः', description: 'संस्कृत ध्वनयः, शब्दरूपाणि एवं सरल संभाषणम्।', estMinutes: 25, learningObjectives: ['संस्कृत अक्षराणां ज्ञानम्', 'शुद्धोच्चारणम्'], status: 'published' },
      { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: 'सुभाषितानि एवं नीतिश्लोकाः', description: 'नीतिवचनानि, श्लोकार्थाः एवं जीवनमूल्यानि।', estMinutes: 30, learningObjectives: ['श्लोकानां कण्ठस्थीकरणम्', 'मूल्यबोधः'], status: 'published' },
      { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: 'धातुरूपाणि एवं वाक्यरचना (Grammar)', description: 'लट्लकारः, लृट्लकारः, पुरुष-वचन प्रयोगः।', estMinutes: 30, learningObjectives: ['क्रियापदानां ज्ञानम्', 'सरल वाक्यनिर्माणम्'], status: 'published' },
      { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: 'सरल कथाः एवं अनुवाद कौशलम्', description: 'पञ्चतन्त्रस्य कथाः एवं हिन्दी-संस्कृत अनुवादः।', estMinutes: 30, learningObjectives: ['कथापठनम्', 'अनुवादसामर्थ्यम्'], status: 'published' },
    ];
  }

  if (sLower.includes('computer') || sLower.includes('coding') || sLower.includes('ai') || sLower.includes('technology') || sLower.includes('informatics') || sLower.includes('digital') || sLower.includes('it')) {
    return [
      { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: isPrimary ? 'Meeting Computer Hardware & Smart Devices' : 'Digital Foundations & System Architecture', description: 'Exploring devices, inputs, processing units, and storage.', estMinutes: isPrimary ? 25 : 45, learningObjectives: ['Understand computing systems', 'Identify hardware and software components'], status: 'published' },
      { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: isPrimary ? 'Creative Tools, Paint & Typing Fun' : 'Algorithms, Flowcharts & Logical Problem Solving', description: 'Interactive creation, step-by-step logic, and tools.', estMinutes: isPrimary ? 25 : 50, learningObjectives: ['Build logical sequences', 'Use application software productively'], status: 'published' },
      { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: isPrimary ? 'Fun with Blocks, Puzzles & Animation' : 'Programming Concepts & Computational Thinking', description: 'Commands, loops, conditionals, and interactive code.', estMinutes: isPrimary ? 30 : 55, learningObjectives: ['Write working code blocks', 'Debug simple logic errors'], status: 'published' },
      { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: isPrimary ? 'Safe Internet Habits & Screen Wellness' : 'Artificial Intelligence, Cyber Safety & Ethics', description: 'Data privacy, AI models, digital citizenship, and safety.', estMinutes: isPrimary ? 25 : 50, learningObjectives: ['Practice safe cyber hygiene', 'Understand AI impact responsibly'], status: 'published' },
    ];
  }

  if (sLower.includes('art') || sLower.includes('craft') || sLower.includes('music') || sLower.includes('dance') || sLower.includes('fine')) {
    return [
      { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: 'Color Theory, Elements of Design & Shapes', description: 'Primary and secondary colors, lines, textures, and rhythm.', estMinutes: 25, learningObjectives: ['Identify visual elements', 'Combine harmonious colors'], status: 'published' },
      { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: 'Techniques, Mediums & Creative Expression', description: 'Pencil shading, water colors, paper folding, and melodies.', estMinutes: 30, learningObjectives: ['Master creative tools', 'Express ideas through art'], status: 'published' },
      { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: 'Cultural Traditions & Folk Art of India', description: 'Madhubani, Warli, classical rhythms, and festive crafts.', estMinutes: 30, learningObjectives: ['Appreciate heritage art forms', 'Create folk patterns'], status: 'published' },
      { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: 'Creative Projects & Showcase Portfolio', description: 'Making greeting cards, models, and personal masterpieces.', estMinutes: 30, learningObjectives: ['Build a creative portfolio', 'Present artistic work with pride'], status: 'published' },
    ];
  }

  if (sLower.includes('physical') || sLower.includes('yoga') || sLower.includes('sports') || sLower.includes('health') || sLower.includes('pe')) {
    return [
      { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: 'Body Fitness, Agility & Warm-up Drills', description: 'Essential stretches, cardio warm-ups, and muscle readiness.', estMinutes: 25, learningObjectives: ['Understand warm-up routines', 'Build daily fitness habits'], status: 'published' },
      { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: 'Yoga Asanas, Posture & Pranayama Breathing', description: 'Tadasana, Vrikshasana, Surya Namaskar, and calm breathing.', estMinutes: 25, learningObjectives: ['Perform foundational asanas', 'Improve posture and mindfulness'], status: 'published' },
      { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: 'Team Sports, Rules & Sportsmanship', description: 'Running, football, cricket, athletics, and fair play ethics.', estMinutes: 30, learningObjectives: ['Understand game rules', 'Cultivate team cooperation'], status: 'published' },
      { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: 'Healthy Nutrition, Rest & Safety First Aid', description: 'Balanced diet, water hydration, sleep, and sports safety.', estMinutes: 25, learningObjectives: ['Make nutritious dietary choices', 'Apply basic sports safety'], status: 'published' },
    ];
  }

  if (sLower.includes('olympiad') || sLower.includes('jee') || sLower.includes('neet') || sLower.includes('competitive') || sLower.includes('reasoning') || sLower.includes('cuet') || sLower.includes('ca_found') || sLower.includes('scholarship')) {
    return [
      { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: 'Logical Reasoning & Pattern Analysis', description: 'Series completion, analogy, coding-decoding, and puzzle grids.', estMinutes: isSenior ? 60 : 35, learningObjectives: ['Solve multi-step logic problems', 'Identify hidden mathematical patterns'], status: 'published' },
      { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: 'Quantitative Aptitude & Rapid Tricks', description: 'Mental shortcuts, percentage logic, ratios, and speed math.', estMinutes: isSenior ? 65 : 35, learningObjectives: ['Execute rapid calculations', 'Apply shortcut techniques accurately'], status: 'published' },
      { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: 'Deep Conceptual High-Yield Drills', description: 'Challenging multi-concept problem scenarios with step derivations.', estMinutes: isSenior ? 70 : 40, learningObjectives: ['Connect multiple concepts', 'Derive solutions methodically'], status: 'published' },
      { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: 'National Championship Mock Test & Speed Mastery', description: 'Timed assessment, negative marking strategies, and PYQs.', estMinutes: isSenior ? 75 : 45, learningObjectives: ['Optimize test speed and accuracy', 'Review error logs for perfection'], status: 'published' },
    ];
  }

  return [
    { id: `ch-${subjectId}-1`, subjectId, gradeId, boardId, number: 1, title: `Foundations of ${subjectName}`, description: `Core definitions, key terminologies, and real-world importance of ${subjectName}.`, estMinutes: isSenior ? 50 : 25, learningObjectives: [`Master foundational concepts of ${subjectName}`, 'Explain core principles in simple terms'], status: 'published' },
    { id: `ch-${subjectId}-2`, subjectId, gradeId, boardId, number: 2, title: `Core Methods & Problem Solving in ${subjectName}`, description: `Step-by-step methodologies, analytical rules, and practical examples.`, estMinutes: isSenior ? 55 : 30, learningObjectives: [`Apply ${subjectName} rules accurately`, 'Solve structured exercises with confidence'], status: 'published' },
    { id: `ch-${subjectId}-3`, subjectId, gradeId, boardId, number: 3, title: `Applications, Case Studies & Real Scenarios`, description: `Real-life applications, scenarios, experiments, and critical thinking.`, estMinutes: isSenior ? 60 : 30, learningObjectives: [`Evaluate real-world scenarios`, 'Connect theory to everyday applications'], status: 'published' },
    { id: `ch-${subjectId}-4`, subjectId, gradeId, boardId, number: 4, title: `Mastery Review, Quizzes & Exam Preparation`, description: `Comprehensive review, tricky problem sets, and full-chapter revision questions.`, estMinutes: isSenior ? 60 : 30, learningObjectives: [`Consolidate full chapter knowledge`, 'Score high marks in assessments'], status: 'published' },
  ];
}
